function inline(s) {
  return esc(s).replace(/\[([^\]]+)\]\(([^)]+)\)/g, (_, label, dest) => {
    const clean = dest.replace(/^&lt;|&gt;$/g, '');
    const link = /^https?:/.test(clean) ? clean : url(path.relative(dir, path.resolve(path.dirname(sourcePath), clean)).replaceAll('\\','/'));
    return `<a href="${link}">${label}</a>`;
  }).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>');
}
