function blocks(md) {
  const lines = md.split('\n'); let out = '', i = 0;
  while (i < lines.length) {
    const s = lines[i].trim();
    if (!s) { i++; continue; }
    if (s.startsWith('### ')) { out += `<h3>${inline(s.slice(4))}</h3>`; i++; continue; }
    if (s.startsWith('|')) {
      const rows = [];
      while (i < lines.length && lines[i].trim().startsWith('|')) {
        rows.push(lines[i].trim().slice(1,-1).split('|').map(x=>x.trim())); i++;
      }
      out += '<dl class="spec-list">' + rows.slice(2).map(row=>`<div><dt>${inline(row[0])}</dt><dd>${row.slice(1).map(inline).join('<span class="spec-break"></span>')}</dd></div>`).join('') + '</dl>';
      continue;
    }
    if (/^- /.test(s)) {
      const items = [];
      while (i < lines.length && /^- /.test(lines[i].trim())) { items.push(lines[i].trim().slice(2)); i++; }
      out += '<ul class="detail-list">' + items.map(x=>'<li>'+inline(x)+'</li>').join('') + '</ul>'; continue;
    }
    if (/^\d+\. /.test(s)) {
      const items=[];
      while(i<lines.length&&/^\d+\. /.test(lines[i].trim())){items.push(lines[i].trim().replace(/^\d+\. /,''));i++;}
      out+='<ol class="detail-list">'+items.map(x=>'<li>'+inline(x)+'</li>').join('')+'</ol>';continue;
    }
    const para=[];
    while(i<lines.length && lines[i].trim() && !/^(### |\||- |\d+\. )/.test(lines[i].trim())) { para.push(lines[i]);i++; }
    out += `<p>${inline(para.join(' '))}</p>`;
  }
  return out;
}
